Community Detection — Gene Modules

# Louvain community detection
community &lt;- cluster_louvain(g, weights = E(g)$weight)

cat("Number of modules:", length(community), "\n")
cat("Modularity:", round(modularity(community), 3), "\n")

# Module membership
module_df &lt;- tibble(
  STRING_id = V(g)$name,
  module    = membership(community)
) |&gt;
  left_join(genes_mapped |&gt; select(STRING_id, gene)) |&gt;
  arrange(module)

# Genes per module
module_df |&gt; count(module) |&gt; arrange(desc(n))

# Functional enrichment per module
module_df |&gt;
  group_by(module) |&gt;
  summarise(genes = list(gene)) |&gt;
  mutate(enrichment = map(genes, ~{
    string_db$get_enrichment(.x)
  }))

Network Proximity — Disease–Drug Distance

# Network proximity: how close are drug targets to disease genes?
# Short distance → drug is mechanistically relevant

# Disease module: genes from our analysis
disease_genes &lt;- V(g)$name

# Drug targets: from DrugBank / Open Targets
drug_targets &lt;- ot_drugs |&gt;
  filter(phase &gt;= 2) |&gt;
  group_by(drug_name) |&gt;
  summarise(targets = list(targetSymbol))

# Compute shortest path distance
# between each drug's targets and our disease genes

compute_proximity &lt;- function(drug_tgts, disease_gns, graph) {
  # Get STRING IDs for drug targets
  dt_ids &lt;- genes_mapped |&gt;
    filter(gene %in% drug_tgts) |&gt;
    pull(STRING_id)

  dg_ids &lt;- genes_mapped |&gt;
    filter(gene %in% disease_gns) |&gt;
    pull(STRING_id)

  if (length(dt_ids) == 0 | length(dg_ids) == 0) return(NA_real_)

  d &lt;- distances(graph, v = dt_ids, to = dg_ids)
  mean(apply(d, 2, min))   # average shortest path
}

# Run for all drugs
drug_proximity &lt;- drug_targets |&gt;
  mutate(proximity = map_dbl(targets, compute_proximity,
                              disease_gns = disease_genes,
                              graph = g)) |&gt;
  arrange(proximity)

head(drug_proximity, 20)

Prioritizing Repositioning Candidates
Combine multiple lines of evidence:

# Final drug prioritization table
drug_priority &lt;- drug_proximity |&gt;
  left_join(cmap_results |&gt;
            select(drug_name, cmap_score = connectivity_score)) |&gt;
  left_join(druggable_hubs |&gt;
            select(drug_name, phase) |&gt;
            group_by(drug_name) |&gt;
            summarise(max_phase = max(phase))) |&gt;
  mutate(
    # Normalize scores 0–1
    proximity_score = 1 - (proximity / max(proximity, na.rm = TRUE)),
    cmap_score_norm = abs(pmin(cmap_score, 0)),

    # Composite repositioning score
    repo_score = (proximity_score * 0.4) +
                 (cmap_score_norm * 0.4) +
                 (max_phase / 4 * 0.2)
  ) |&gt;
  arrange(desc(repo_score))

head(drug_priority, 15)

Heatmap of Top Species

library(ComplexHeatmap)

# Top 30 most variable species
top_species &lt;- species |&gt;
  rowwise() |&gt;
  mutate(variance = var(c_across(where(is.numeric)))) |&gt;
  ungroup() |&gt;
  slice_max(variance, n = 30)

mat &lt;- top_species |&gt;
  select(-c(`#clade_name`, NCBI_tax_id, variance)) |&gt;
  column_to_rownames("species") |&gt;
  as.matrix()

# Heatmap with annotation
ha &lt;- HeatmapAnnotation(
  Group = sample_data$Group,
  col   = list(Group = c(IBD = "#D85A30", Control = "#1D9E75"))
)

Heatmap(
  log10(mat + 1e-4),
  name            = "log10(rel. abund.)",
  top_annotation  = ha,
  show_column_names = FALSE,
  clustering_distance_rows = "pearson"
)

Hands-On: Find Dysbiotic Taxa

# Differential abundance: CD vs. nonIBD
ps_cd &lt;- subset_samples(ps_ibd, diagnosis %in% c("CD", "nonIBD"))
dds   &lt;- phyloseq_to_deseq2(ps_cd, ~ diagnosis)
dds   &lt;- DESeq(dds)
res   &lt;- results(dds, contrast = c("diagnosis", "CD", "nonIBD"),
                  cooksCutoff = FALSE)

# Annotate with taxonomy
res_df &lt;- res |&gt;
  as_tibble(rownames = "ASV") |&gt;
  filter(!is.na(padj)) |&gt;
  left_join(as.data.frame(tax_table(ps_ibd)) |&gt;
            rownames_to_column("ASV")) |&gt;
  arrange(padj)

# Top depleted in CD (dysbiosis signature)
res_df |&gt;
  filter(padj &lt; 0.05, log2FoldChange &lt; -1) |&gt;
  select(Genus, Species, log2FoldChange, padj)

Convergent Evidence Scoring

# Combine multiple lines of evidence
# Each layer contributes points toward gene prioritization

gene_scores &lt;- tibble(gene = all_candidate_genes) |&gt;

  # 1. GWAS: MAGMA gene p-value
  left_join(magma_genes |&gt; select(gene = GENE, magma_p = P)) |&gt;
  mutate(score_gwas = -log10(magma_p)) |&gt;

  # 2. eQTL colocalization
  left_join(coloc_results |&gt; select(gene, pp_h4)) |&gt;
  mutate(score_coloc = ifelse(pp_h4 &gt; 0.8, 3, 0)) |&gt;

  # 3. scRNA-seq — expressed in disease cell type?
  left_join(scrna_markers |&gt; select(gene, avg_log2FC)) |&gt;
  mutate(score_scrna = ifelse(avg_log2FC &gt; 0.5, 2, 0)) |&gt;

  # 4. ATAC-seq — SNP in open chromatin?
  left_join(atac_overlap |&gt; select(gene, in_peak)) |&gt;
  mutate(score_atac = ifelse(in_peak, 2, 0)) |&gt;

  # Total convergent score
  mutate(total_score = score_gwas + score_coloc +
                       score_scrna + score_atac) |&gt;
  arrange(desc(total_score))

